SigilValue sigil_String____to_uppercase(SigilValue s) {
    if (s.tag != TAG_STRING || !s.v.s) return sigil_string("");
    size_t len = strlen(s.v.s);
    char* result = (char*)malloc(len + 1);
    for (size_t i = 0; i < len; i++) {
        result[i] = (s.v.s[i] >= 'a' && s.v.s[i] <= 'z') ? s.v.s[i] - 32 : s.v.s[i];
    }
    result[len] = '\0';
    return (SigilValue){ .tag = TAG_STRING, .evidence = SIGIL_KNOWN, .v.s = result };
}

SigilValue sigil_String____to_lowercase(SigilValue s) {
    if (s.tag != TAG_STRING || !s.v.s) return sigil_string("");
    size_t len = strlen(s.v.s);
    char* result = (char*)malloc(len + 1);
    for (size_t i = 0; i < len; i++) {
        result[i] = (s.v.s[i] >= 'A' && s.v.s[i] <= 'Z') ? s.v.s[i] + 32 : s.v.s[i];
    }
    result[len] = '\0';
    return (SigilValue){ .tag = TAG_STRING, .evidence = SIGIL_KNOWN, .v.s = result };
}

