/* File I/O functions for FFI */
static size_t __sigil_last_file_len = 0;

SigilValue sigil_read_file(SigilValue path, SigilValue len) {
    if (path.tag != TAG_STRING || !path.v.s) return sigil_null();
    FILE* f = fopen(path.v.s, "rb");
    if (!f) return sigil_null();
    fseek(f, 0, SEEK_END);
    size_t size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char* buf = (char*)malloc(size + 1);
    fread(buf, 1, size, f);
    buf[size] = '\0';
    fclose(f);
    __sigil_last_file_len = size;
    return sigil_string(buf);
}

SigilValue sigil_file_len(void) {
    return sigil_int(__sigil_last_file_len);
}

SigilValue sigil_write_file(SigilValue path, SigilValue path_len, SigilValue content, SigilValue content_len) {
    (void)path_len; (void)content_len; /* length params unused - null-terminated */
    if (path.tag != TAG_STRING || !path.v.s) return sigil_bool(false);
    if (content.tag != TAG_STRING || !content.v.s) return sigil_bool(false);
    FILE* f = fopen(path.v.s, "w");
    if (!f) return sigil_bool(false);
    fputs(content.v.s, f);
    fclose(f);
    return sigil_bool(true);
}

