SigilValue sigil_Vec____join(SigilValue arr, SigilValue sep) {
    if (arr.tag != TAG_ARRAY) return sigil_string("");
    if (arr.v.arr.len == 0) return sigil_string("");
    const char* sep_str = (sep.tag == TAG_STRING && sep.v.s) ? sep.v.s : "";
    size_t total_len = 0;
    size_t sep_len = strlen(sep_str);
    for (size_t i = 0; i < arr.v.arr.len; i++) {
        SigilValue s = sigil_display(arr.v.arr.data[i]);
        if (s.tag == TAG_STRING && s.v.s) total_len += strlen(s.v.s);
        if (i > 0) total_len += sep_len;
    }
    char* result = (char*)malloc(total_len + 1);
    result[0] = '\0';
    for (size_t i = 0; i < arr.v.arr.len; i++) {
        if (i > 0) strcat(result, sep_str);
        SigilValue s = sigil_display(arr.v.arr.data[i]);
        if (s.tag == TAG_STRING && s.v.s) strcat(result, s.v.s);
    }
    return (SigilValue){ .tag = TAG_STRING, .evidence = SIGIL_KNOWN, .v.s = result };
}

SigilValue sigil_push(SigilValue arr, SigilValue item) {
    if (arr.tag != TAG_ARRAY || !arr.v.arr.data) return arr;
    SigilArrayHeader* header = sigil_get_array_header(arr.v.arr.data);
    if (header->cap == 0 || header->cap > 10000000 || header->len > header->cap) return arr;
    if (header->len >= header->cap) {
        size_t new_cap = header->cap == 0 ? 4 : header->cap * 2;
        SigilArrayHeader* new_header = (SigilArrayHeader*)realloc(header, SIGIL_ARRAY_DATA_OFFSET + new_cap * sizeof(SigilValue));
        new_header->cap = new_cap; header = new_header;
        arr.v.arr.data = (SigilValue*)sigil_array_data(header); arr.v.arr.cap = new_cap;
    }
    ((SigilValue*)sigil_array_data(header))[header->len++] = item;
    arr.v.arr.len = header->len;
    return arr;
}

SigilValue sigil_zip(SigilValue a, SigilValue b) {
    if (a.tag != TAG_ARRAY || b.tag != TAG_ARRAY) return sigil_array(0);
    size_t len = a.v.arr.len < b.v.arr.len ? a.v.arr.len : b.v.arr.len;
    SigilValue result = sigil_array(len);
    for (size_t i = 0; i < len; i++) {
        SigilValue* fields = (SigilValue*)malloc(2 * sizeof(SigilValue));
        fields[0] = a.v.arr.data[i];
        fields[1] = b.v.arr.data[i];
        result.v.arr.data[i] = (SigilValue){ .tag = TAG_TUPLE, .evidence = SIGIL_KNOWN };
        result.v.arr.data[i].v.tup.fields = fields;
        result.v.arr.data[i].v.tup.count = 2;
    }
    return result;
}

SigilValue sigil_all(SigilValue arr, SigilValue closure) {
    if (arr.tag != TAG_ARRAY) return sigil_bool(true);
    typedef SigilValue (*ClosureFn)(SigilValue);
    ClosureFn fn = (ClosureFn)closure.v.ptr;
    for (size_t i = 0; i < arr.v.arr.len; i++) {
        SigilValue result = fn(arr.v.arr.data[i]);
        if (!sigil_truthy(result)) return sigil_bool(false);
    }
    return sigil_bool(true);
}

