/* Main entry point */
int main(int argc, char** argv) {
    /* Build args array from command line */
    SigilValue args = sigil_Vec____new();
    for (int i = 1; i < argc; i++) {
        args = sigil_push(args, sigil_string(argv[i]));
    }
    SigilValue result = sigil_main(args);
    return (result.tag == TAG_INT) ? (int)result.v.i : 0;
}
